package org.evox.spen.compat;
import android.app.Instrumentation;import android.view.KeyEvent;import android.util.Log;import java.io.*;import java.util.*;
/** Preserve Samsung's queued DOWN/UP events, modifiers and repeat counts inside the original package. */
public final class InputAccess {
 private static final Map<KeyEvent,Integer> displays=Collections.synchronizedMap(new WeakHashMap<KeyEvent,Integer>());
 private static Process worker;private static BufferedReader results;private static PrintWriter requests;
 public static void setDisplay(KeyEvent e,int display){displays.put(e,display);}
 private static String readResult()throws Exception{long end=System.nanoTime()+3000000000L;while(System.nanoTime()<end){if(results.ready()){String line=results.readLine();if(line==null)throw new IOException("Root input worker exited");return line;}if(!worker.isAlive())throw new IOException("Root input worker exited");Thread.sleep(10);}throw new IOException("Root input worker timeout");}
 private static void start()throws Exception{if(worker!=null&&worker.isAlive())return;String apk=RuntimeContext.app().getApplicationInfo().sourceDir;worker=new ProcessBuilder("su","-c","CLASSPATH="+RootAccess.quote(apk)+" app_process /system/bin org.evox.spen.compat.RootInputMain").start();results=new BufferedReader(new InputStreamReader(worker.getInputStream()));requests=new PrintWriter(worker.getOutputStream(),true);if(!"READY".equals(readResult()))throw new IOException("Root input initialization failed");}
 public static synchronized boolean inject(KeyEvent e){try{start();Integer display=displays.remove(e);int source=e.getSource()==0?257:e.getSource();requests.println(e.getDownTime()+" "+e.getEventTime()+" "+e.getAction()+" "+e.getKeyCode()+" "+e.getRepeatCount()+" "+e.getMetaState()+" "+e.getDeviceId()+" "+e.getScanCode()+" "+(e.getFlags()&~0x02000000)+" "+source+" "+(display==null?DisplayAccess.focusedId():display));String result=readResult();if(!"OK".equals(result))throw new IOException("Root input rejected event: "+result);Log.d("AirCommandPort","Original key injected action="+e.getAction()+" code="+e.getKeyCode());return true;}catch(Exception failure){Log.e("AirCommandPort","Original key injection failed: "+failure.getClass().getSimpleName());if(worker!=null)worker.destroy();worker=null;return false;}}
 public static void send(Instrumentation ignored,KeyEvent e){inject(e);}
 public static void shell(String command){if(!command.matches("input(?: (?:touchscreen|keyboard|stylus))?(?: -d -?[0-9]+)? (?:swipe|tap|keyevent|motionevent|keycombination) [-A-Za-z0-9. ]+")){Log.e("AirCommandPort","Rejected unexpected original input command");return;}try{RootAccess.run(command);}catch(Exception failure){Log.e("AirCommandPort","Original touch injection failed: "+failure.getClass().getSimpleName());}}
}
